/**
 * The links between the sibling pages of one section, with the current page marked (`design/components/section-nav.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/section-nav.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentMember,
  agentPress,
  claimSlot,
  createDerived,
  elementRef,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/section-nav.module.css'

export interface SectionNavItem {
  label: string
  href: string
}

export interface SectionNavProps {
  /**
   * The `href` of the item whose page the reader is on; without it no item is current. It is
   * compared as the page it names, so a trailing slash, a query or a hash on either side does
   * not stop the match, and neither does an origin on `current` (`location.href`).
   */
  current?: string
  /**
   * One link per sibling page, in the order drawn.
   */
  items: SectionNavItem[]
  /**
   * The landmark's accessible name, which tells this navigation from the page's others.
   */
  label: string
  /**
   * The app's router, for every item (`link.md` §Routing): a click that would navigate this tab
   * calls it in place of the browser.
   */
  onNavigate?: (href: string) => void
}

/** The links between the sibling pages of one section, with the current page marked. */
export default function SectionNav(given: SectionNavProps): JSX.Element {
  const props = claimSlot(given)
  const root = elementRef<HTMLElement>()
  const originOf = createDerived(
    () =>
      (href: string): string | undefined =>
        /^(?:[a-z][a-z\d+.-]*:)?\/\/[^/?#]*/iu.exec(href)?.[0].toLowerCase(),
  )
  const pageOf = createDerived(() => (href: string): string => {
    if (href.startsWith('#') || href.startsWith('?')) return href
    const origin = originOf.value(href) ?? ''
    const path = href.slice(origin.length).replace(/[?#].*$/u, '')
    if (path === '') return origin === '' ? '' : '/'
    return path.length > 1 ? path.replace(/\/+$/u, '') : path
  })
  const currentAt = createDerived(() =>
    ((at: string | undefined): number => {
      if (at === undefined) return -1
      const exact = props.items.findIndex((item) => item.href === at)
      if (exact !== -1) return exact
      const page = pageOf.value(at)
      const origin = originOf.value(at)
      return props.items.findIndex((item) => {
        const itemOrigin = originOf.value(item.href)
        return (
          pageOf.value(item.href) === page && (itemOrigin === undefined || itemOrigin === origin)
        )
      })
    })(props.current),
  )
  const navigatesHere = createDerived(
    () =>
      (event: MouseEvent): boolean =>
        !event.defaultPrevented &&
        event.button === 0 &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.shiftKey &&
        !event.altKey,
  )
  const route = createDerived(() => (event: MouseEvent, href: string): void => {
    if (!(props.onNavigate !== undefined) || !navigatesHere.value(event)) return
    event.preventDefault()
    props.onNavigate?.(href)
  })
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran = agentMember({
      member: 'SectionNav',
      element: () => root.value,
      state: () => ({
        current: props.items[currentAt.value]?.href ?? null,
        items: props.items
          .filter((item, at) => props.items.findIndex((other) => other.href === item.href) === at)
          .map((item) => ({ id: item.href, label: item.label })),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) =>
            agentPress(
              root.value?.querySelectorAll('a')[
                props.items.findIndex((item) => item.href === value)
              ],
            ),
        },
      },
    })
    release1 = () => {
      ran()
    }
  }
  onMount(effect1)
  onCleanup(() => release1?.())
  return (
    <nav class={styles.nav} aria-label={props.label} data-member="section-nav" ref={root.attach}>
      {/* list */}
      <ul class={styles.list}>
        <Each of={props.items} by={(item, index) => `${index}:${item.href}`} renew>
          {(item, index) => (
            <li class={styles.item}>
              <a
                class={styles.link}
                href={item.href}
                aria-current={index() === currentAt.value ? 'page' : undefined}
                onclick={($event: MouseEvent) => route.value($event, item.href)}
              >
                {/* label */}
                <span class={styles.label}>{item.label}</span>
              </a>
            </li>
          )}
        </Each>
      </ul>
    </nav>
  )
}
